Think: Extract whitespace-separated tokens from each clean_<filename> and write them one per line to tokens_<filename> using awk that reads the manifest to get filenames.

Act: bash

```bash
awk '{
 fname=$1;
 infile="temp_workspace/clean_"fname;
 outfile="temp_workspace/tokens_"fname;
 first=1;
 while((getline line < infile) > 0){
   n=split(line,a,/[[[:space:]]]+/);
   for(i=1;i<=n;i++){
     if(a[i]!=""){
       if(first){ print a[i] > outfile; first=0 } else print a[i] >> outfile
     }
   }
 }
 close(infile);
 close(outfile);
}' temp_workspace/file_list.txt
```

