Think: Create the script peak_login_task/count_peak_logins.sh with a header, description, placeholders, and a single command (awk) that extracts timestamps, records invalid lines, filters peak times (21:00-23:59), writes extracted_times.txt, invalid_entries.log, peak_times.txt, peak_count.txt, and prints only the integer. Use a heredoc to create the file in one bash action.

Act: bash

```bash
cat > peak_login_task/count_peak_logins.sh <<'EOF'
#!/bin/bash
# count_peak_logins.sh
# Description: Count logins between 21:00 and 23:59 (inclusive) from the input server.log.
# Input placeholder: peak_login_task/server.log
# Output placeholder: peak_login_task/peak_count.txt
# Additional outputs produced: peak_login_task/extracted_times.txt, peak_login_task/invalid_entries.log, peak_login_task/peak_times.txt
awk 'BEGIN{
  ex="peak_login_task/extracted_times.txt"; inv="peak_login_task/invalid_entries.log"; peakf="peak_login_task/peak_times.txt"; countf="peak_login_task/peak_count.txt";
  # Truncate/create output files
  print "" > ex; print "" > inv; print "" > peakf;
  peak=0;
}
{
  if (match($0,/^([0-9]{1,2}):([0-9]{2})/,a)) {
    h = a[1] + 0;
    m = a[2] + 0;
    if (h>=0 && h<=23 && m>=0 && m<=59) {
      t = sprintf("%02d:%02d", h, m);
      print t >> ex;
      if (h>=21 && h<=23) { print t >> peakf; peak++; }
    } else {
      print $0 >> inv;
    }
  } else {
    print $0 >> inv;
  }
}
END{
  print peak > countf;
  # Print only the integer count to stdout as required
  print peak;
}' peak_login_task/server.log
EOF
