Think: Verify each canonical path in regular_unique.txt is under /working and is a regular file; record any discrepancies to temp_workspace_check/consistency_report.txt.

Act: bash

```bash
awk -v OFS=$'\t' '{
 path=$0
 if (path=="") next
 if (path !~ "^/working(/|$)") { print path, "NOT_UNDER_WORKING"; next }
 cmd = "stat -c %F \"" path "\" 2>/dev/null"
 f = ""; cmd | getline f; close(cmd)
 if (f == "") { print path, "MISSING"; next }
 if (f != "regular file") { print path, "TYPE_MISMATCH:" f; next }
 print path, "OK"
}' temp_workspace_check/regular_unique.txt > temp_workspace_check/consistency_report.txt
